/* Practice Desk backend — one file, zero dependencies (Node 18+).
 *
 * Serves the frontend (index.html, styles.css, config.js, client.js, app.js)
 * and the API in API.md from the same origin, so apiBase "/api" just works.
 *
 * Run:   node server.js            → http://localhost:5173
 * Needs: GEMINI_API_KEY in .env    → https://aistudio.google.com/apikey
 *
 * Everything a student sees is real: the agent language is generated by
 * Gemini, tasks are graded on the server against their own requirements,
 * quiz answers never reach the browser, and each student's desk is their own
 * (cookie session, stored on this machine under data/).
 */

const http = require("http");
const fs = require("fs");
const fsp = require("fs/promises");
const path = require("path");
const crypto = require("crypto");

/* ── environment ─────────────────────────────────────────────── */
(function loadDotEnv() {
  try {
    const raw = fs.readFileSync(path.join(__dirname, ".env"), "utf8");
    for (const line of raw.split("\n")) {
      const m = /^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/.exec(line);
      if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2];
    }
  } catch {}
})();

const KEYS = (process.env.GEMINI_API_KEY || "")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);
const PORT = Number(process.env.PORT) || 5173;
/* Tried in order: the first that answers is used, so a busy or retired
   model never breaks the desk. */
const MODELS = ["gemini-3-flash-preview", "gemini-3.8-flash", "gemini-3.5-flash-lite"];

if (!KEYS.length) {
  console.error("Missing GEMINI_API_KEY. Create .env with GEMINI_API_KEY=… (aistudio.google.com/apikey)");
  process.exit(1);
}

/* ── small utilities ──────────────────────────────────────────── */
const uid = () => crypto.randomBytes(9).toString("base64url");
const today = () => new Date().toISOString().slice(0, 10);
const words = (t) => String(t || "").split(/\s+/).filter(Boolean).length;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const T = { STRING: "STRING", INTEGER: "INTEGER", BOOLEAN: "BOOLEAN" };
const S = {
  str: { type: T.STRING },
  int: { type: T.INTEGER },
  bool: { type: T.BOOLEAN },
  obj: (properties, required) => ({ type: "OBJECT", properties, required }),
  arr: (items) => ({ type: "ARRAY", items }),
  opt: (schema) => ({ ...schema, nullable: true }),
};

/* ── Gemini ───────────────────────────────────────────────────── */
async function ask({ system, user, schema, temperature = 0.7 }) {
  const base = {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: "user", parts: [{ text: user }] }],
  };

  // try every (model, key) pair: a key with quota left answers even when
  // another is busy or has used up its free daily allowance
  const combos = [];
  for (const model of MODELS) for (const key of KEYS) combos.push({ model, key });

  let lastErr = null;
  for (const { model, key } of combos) {
    // lite models reject thinkingConfig, so it is only sent to full models
    const lite = /lite/i.test(model);
    const payload = {
      ...base,
      generationConfig: {
        temperature,
        maxOutputTokens: 2000,
        ...(lite ? {} : { thinkingConfig: { thinkingBudget: 0 } }),
        ...(schema ? { responseMimeType: "application/json", responseSchema: schema } : {}),
      },
    };

    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const res = await fetch(
          `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
          {
            method: "POST",
            headers: { "content-type": "application/json", "x-goog-api-key": key },
            body: JSON.stringify(payload),
            signal: AbortSignal.timeout(30000),
          }
        );

        if (!res.ok) {
          let msg = "";
          try {
            msg = (await res.json()).error?.message || "";
          } catch {}
          if (res.status === 429) {
            if (/per day/i.test(msg)) {
              // this model's free-tier daily limit is used up: no point waiting
              lastErr = new Error("This model's free daily limit is used up.");
              break;
            }
            // per-minute limit: it clears within the minute, so wait it out
            lastErr = new Error(
              "The AI service hit its free-tier limit for a moment. It clears shortly — try again."
            );
            await sleep(attempt === 0 ? 15000 : 25000);
            continue;
          }
          if (res.status === 503) {
            // demand spikes last longer than a retry; the next model is faster
            lastErr = new Error("The AI service is busy right now. Try again in a moment.");
            break;
          }
          // wrong or unavailable model: move to the next one straight away
          lastErr = new Error(msg || `The AI service answered ${res.status}.`);
          break;
        }

        const data = await res.json();
        const parts = data.candidates?.[0]?.content?.parts || [];
        const text = parts.map((p) => p.text || "").join("").trim();
        if (!text) {
          lastErr = new Error("The AI service returned an empty answer.");
          await sleep(500);
          continue;
        }
        if (!schema) return text;
        try {
          return JSON.parse(text);
        } catch {
          lastErr = new Error("The AI service returned something unreadable.");
          await sleep(500);
          continue;
        }
      } catch (e) {
        if (e.name === "TimeoutError" || e.name === "AbortError") {
          lastErr = new Error("The AI service took too long. Try again.");
          break; // try the next model instead of waiting twice
        }
        lastErr = new Error("The AI service could not be reached. Check your connection.");
        await sleep(500);
      }
    }
  }
  throw lastErr || new Error("The AI service could not be reached.");
}

